import React, { useState, useRef, useEffect, useMemo, useCallback } from 'react';
import { Flow } from 'flow-sdk';
import { Play, Pause, RotateCcw, Box, Settings, Trash2, FastForward, Rewind, Repeat, Plus, Minus, Sun, Moon, Activity, Focus, Scissors, X, FolderOpen } from 'lucide-react';
import { parseGIF, decompressFrames } from 'gifuct-js';
import { removeBackgroundFromFrame, getSegmenter } from './services/segmentation';
import { cn } from './lib/utils';
import { useSceneRecorder } from './scene/useSceneRecorder';
import { renderScene, projectFrameQuads, pointInQuad, quadsBoundingBox, type SceneState, type SceneGif, type MotionPreset } from './scene/renderer';

// Decode a base64 string into a Uint8Array (browser-safe).
function base64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

// Evenly sample N indices from a frame array (always includes index 0).
// pct=0 → 1 frame; pct=1 → all frames; intermediate → evenly spaced subset.
function sampleIndices(total: number, pct: number): number[] {
  if (total <= 0) return [];
  const clamped = Math.max(0, Math.min(1, pct));
  const count = Math.max(1, Math.round(clamped * total));
  if (count >= total) return Array.from({ length: total }, (_, i) => i);
  if (count === 1) return [0];
  const out: number[] = [];
  for (let k = 0; k < count; k++) {
    out.push(Math.round((k * (total - 1)) / (count - 1)));
  }
  return out;
}

type GifData = {
  id: string;
  name: string;
  frames: string[];
  x: number;
  y: number;
  rotZ?: number;
  isSegmented?: boolean;
  styleMode?: 'normal' | 'hologram' | 'neon' | 'ghost';
};

type PlaybackMode = 'forward' | 'reverse' | 'ping-pong';

const SliderControl = ({ 
  label, value, min, max, step = 1, onChange, onReset, formatValue = (v: number) => v.toString(), theme 
}: { 
  label: string; value: number; min: number; max: number; step?: number; 
  onChange: (v: number) => void; onReset: () => void; formatValue?: (v: number) => string; theme: string;
}) => (
  <div className="space-y-1">
    <div className="flex justify-between items-center text-[9px]">
      <label className={theme === 'light' ? 'text-black/50' : 'text-white/50'}>{label}</label>
      <div className="flex items-center gap-1">
        <span>{formatValue(value)}</span>
        <button onClick={onReset} className="opacity-50 hover:opacity-100 transition-opacity" title="Reset to default">
          <RotateCcw className="w-2.5 h-2.5" />
        </button>
      </div>
    </div>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={(e) => onChange(Number(e.target.value))}
      className="h-1 w-full"
    />
  </div>
);

export default function App() {
  const [theme, setTheme] = useState<'dark' | 'light'>('light');
  const [lightBgColor, setLightBgColor] = useState('#f3f4f6');
  const [darkBgColor, setDarkBgColor] = useState('#111111');
  const [gifs, setGifs] = useState<GifData[]>([]);
  const [selectedGifId, setSelectedGifId] = useState<string | null>(null);
  const [draggingGifId, setDraggingGifId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [segmentationProgress, setSegmentationProgress] = useState<{ id: string; current: number; total: number; startTime: number } | null>(null);

  // View Parameters (Camera) — match original CSS-3D defaults: rotateX=60°, rotateZ=45°.
  const [rotationX, setRotationX] = useState(60);
  const [rotationZ, setRotationZ] = useState(45);
  const [scale, setScale] = useState(1);

  // Transform & Visual Parameters
  const [depth, setDepth] = useState(200);
  const [shearOffset, setShearOffset] = useState(0);
  const [scaleStep, setScaleStep] = useState(1);
  const [multiGifSpread, setMultiGifSpread] = useState(150);

  // Motion
  const [motionPreset, setMotionPreset] = useState<MotionPreset>('none');
  const [motionIntensity, setMotionIntensity] = useState(1);

  // Architectural & Material Parameters
  const [dropShadow, setDropShadow] = useState(0);

  // Pan State
  const [panX, setPanX] = useState(0);
  const [panY, setPanY] = useState(0);
  const [isPanning, setIsPanning] = useState(false);

  // Playback State
  const [isPlaying, setIsPlaying] = useState(false);
  // Frame density: 0 → 1 frame visible (front of stack); 1 → all frames.
  // Per-gif evenly sampled indices are derived in `gifIndices` below.
  const [framePercent, setFramePercent] = useState(1);
  // Cursor that advances during playback. Each gif's frame at render time is
  // `gif.indices[(cursor + offset) mod indices.length]`. The cursor is a float
  // in frames so playback speed and direction can drive it smoothly.
  const [playbackCursor, setPlaybackCursor] = useState(0);
  const [playbackSpeed, setPlaybackSpeed] = useState(100);
  const [playbackMode, setPlaybackMode] = useState<PlaybackMode>('forward');
  const [pingPongDir, setPingPongDir] = useState<'forward' | 'reverse'>('forward');

  const containerRef = useRef<HTMLDivElement>(null);
  const isDraggingCanvasRef = useRef(false);
  const lastMousePosRef = useRef({ x: 0, y: 0 });
  const abortFlagsRef = useRef<Record<string, boolean>>({});

  // Background-removal model load status. Preloaded on mount (see effect
  // below), so by the time the user clicks "segment" the model is usually
  // already warm. `error` is non-fatal: a click will retry via the cache
  // reset in getSegmenter().
  const [modelStatus, setModelStatus] = useState<'loading' | 'ready' | 'error'>('loading');
  const sceneCanvasRef = useRef<HTMLCanvasElement>(null);
  const sceneStartTimeRef = useRef<number>(performance.now());
  // Cache of decoded frame images so the rAF loop can blit them synchronously.
  const imgCacheRef = useRef<Map<string, HTMLImageElement>>(new Map());
  // Quads of the most recently painted frame, for hit-testing on click.
  const lastQuadsRef = useRef<Array<{ gifId: string; frameIdx: number; tl: { x: number; y: number }; tr: { x: number; y: number }; br: { x: number; y: number }; bl: { x: number; y: number } }>>([]);

  const {
    isRecording,
    isSaving: isSavingRecording,
    error: recError,
    toast: recToast,
    start: startRecording,
    stop: stopRecording,
  } = useSceneRecorder(sceneCanvasRef);

  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    if (recError) setError(`RECORDING FAILED: ${recError.toUpperCase()}.`);
  }, [recError]);

  useEffect(() => {
    if (recToast) {
      setToastMessage(recToast);
      const t = setTimeout(() => setToastMessage(null), 3000);
      return () => clearTimeout(t);
    }
  }, [recToast]);

  // Warm the background-removal model in the background so the first
  // segmentation feels instant. Failure here is non-fatal: getSegmenter()
  // resets its internal cache on error, so a later click will retry.
  useEffect(() => {
    let cancelled = false;
    getSegmenter()
      .then(() => {
        if (!cancelled) setModelStatus('ready');
      })
      .catch((err) => {
        console.warn('[App] Background model preload failed:', err);
        if (!cancelled) setModelStatus('error');
      });
    return () => {
      cancelled = true;
    };
  }, []);

  // Decode missing frames into the image cache whenever the gifs list changes.
  useEffect(() => {
    const cache = imgCacheRef.current;
    for (const g of gifs) {
      for (const src of g.frames) {
        if (cache.has(src)) continue;
        const img = new Image();
        img.src = src;
        cache.set(src, img);
        // Best-effort decode; fine if it fails — renderer skips incomplete images.
        // @ts-ignore
        if (img.decode) img.decode().catch(() => { /* ignore */ });
      }
    }
  }, [gifs]);

  // Per-gif evenly-sampled frame indices, derived from framePercent.
  // Each gif samples its own frame count, so a 10-frame gif and a 100-frame gif
  // both render proportionally at any density.
  const gifIndices = useMemo(() => {
    const map: Record<string, number[]> = {};
    for (const g of gifs) map[g.id] = sampleIndices(g.frames.length, framePercent);
    return map;
  }, [gifs, framePercent]);

  // Scene render loop: paints the canvas on every animation frame using the
  // latest React state (closure captures the most recent values each re-render,
  // but we use a ref-based access pattern so the loop itself runs once).
  const sceneStateLiveRef = useRef<SceneState | null>(null);
  useEffect(() => {
    const cache = imgCacheRef.current;
    const bgColor = theme === 'light' ? lightBgColor : darkBgColor;
    const sceneGifs: SceneGif[] = gifs.map(g => {
      const baseIndices = gifIndices[g.id] || sampleIndices(g.frames.length, framePercent);
      // Apply playback cursor: progressively reveal frames from 0 up to cursor.
      let renderIndices = baseIndices;
      if (isPlaying && baseIndices.length > 1) {
        const len = baseIndices.length;
        const off = ((Math.floor(playbackCursor) % len) + len) % len;
        renderIndices = baseIndices.slice(0, off + 1);
      }
      return {
        id: g.id,
        x: g.x,
        y: g.y,
        rotZ: g.rotZ || 0,
        styleMode: (g.styleMode === 'hologram' || g.styleMode === 'neon' || g.styleMode === 'ghost') ? g.styleMode : 'none',
        totalStackSize: baseIndices.length,
        frames: g.frames.map(src => {
          let img = cache.get(src);
          if (!img) {
            img = new Image();
            img.src = src;
            cache.set(src, img);
          }
          return img;
        }),
        indices: renderIndices,
      };
    });
    sceneStateLiveRef.current = {
      gifs: sceneGifs,
      rotationX, rotationZ, scale, panX, panY,
      depth, shearOffset, scaleStep,
      dropShadow, multiGifSpread,
      motionPreset, motionIntensity, theme, bgColor,
    };
  }, [gifs, gifIndices, framePercent, isPlaying, playbackCursor, rotationX, rotationZ, scale, panX, panY, depth, shearOffset, scaleStep, dropShadow, multiGifSpread, motionPreset, motionIntensity, theme, lightBgColor, darkBgColor]);

  useEffect(() => {
    let raf = 0;
    const loop = () => {
      const canvas = sceneCanvasRef.current;
      const state = sceneStateLiveRef.current;
      if (canvas && state) {
        // Keep canvas backing store in sync with its CSS size (1:1, no DPR scaling —
        // keeps projection math and hit-testing in the same coordinate space and is
        // what MediaRecorder captures).
        const rect = canvas.getBoundingClientRect();
        const targetW = Math.max(2, Math.round(rect.width));
        const targetH = Math.max(2, Math.round(rect.height));
        if (canvas.width !== targetW) canvas.width = targetW;
        if (canvas.height !== targetH) canvas.height = targetH;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          const t = performance.now() - sceneStartTimeRef.current;
          renderScene(ctx, state, t);
          lastQuadsRef.current = projectFrameQuads(state, targetW, targetH, t);
        }
      }
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, []);


  const maxFramesAcrossGifs = Math.max(1, ...gifs.map(g => g.frames.length));

  // Playback loop: advance a cursor in source-frame units. Each render maps the
  // cursor onto each gif's sampled `indices` via modulo so multi-gif and
  // density changes don't desync.
  useEffect(() => {
    if (!isPlaying || gifs.length === 0) return;
    const interval = window.setInterval(() => {
      setPlaybackCursor((prev) => {
        if (playbackMode === 'forward') {
          return (prev + 1) % maxFramesAcrossGifs;
        } else if (playbackMode === 'reverse') {
          return (prev - 1 + maxFramesAcrossGifs) % maxFramesAcrossGifs;
        } else {
          // ping-pong
          if (pingPongDir === 'forward') {
            if (prev >= maxFramesAcrossGifs - 1) {
              setPingPongDir('reverse');
              return prev - 1;
            }
            return prev + 1;
          } else {
            if (prev <= 0) {
              setPingPongDir('forward');
              return prev + 1;
            }
            return prev - 1;
          }
        }
      });
    }, playbackSpeed);
    return () => clearInterval(interval);
  }, [isPlaying, gifs.length, playbackSpeed, playbackMode, pingPongDir, maxFramesAcrossGifs]);

  // Handle Native Wheel for Zoom to prevent browser zoom
  useEffect(() => {
    const canvas = containerRef.current;
    if (!canvas) return;

    const handleNativeWheel = (e: WheelEvent) => {
      if ((e.target as HTMLElement).closest('.controls-panel')) return;
      if ((e.target as HTMLElement).closest('.hud-controls')) return;
      e.preventDefault();
      setScale(s => Math.max(0.1, Math.min(10, s - e.deltaY * 0.005)));
    };

    canvas.addEventListener('wheel', handleNativeWheel, { passive: false });
    return () => canvas.removeEventListener('wheel', handleNativeWheel);
  }, []);

  // When playback stops, reset the cursor so the front of the stack returns
  // to the original frame ordering.
  useEffect(() => {
    if (!isPlaying) setPlaybackCursor(0);
  }, [isPlaying]);

  const handleBrowseGallery = async () => {
    if (gifs.length >= 5) {
      setError('MAXIMUM 5 ALLOWED.');
      return;
    }
    try {
      const media = await Flow.media.select({ filter: 'video' });
      if (!media) return;
      await processVideo(media);
    } catch (err) {
      // user cancelled or sandbox denied
      console.warn('media.select failed', err);
    }
  };

  const processVideo = async (media: { base64: string; mimeType: string; name?: string }) => {
    setIsLoading(true);
    setError(null);

    const bytes = base64ToBytes(media.base64);
    const blob = new Blob([bytes], { type: media.mimeType || 'video/mp4' });
    const url = URL.createObjectURL(blob);
    const video = document.createElement('video');
    video.preload = 'auto';
    video.playsInline = true;
    video.muted = true;
    video.src = url;

    try {
      await new Promise<void>((resolve, reject) => {
        video.onloadeddata = () => resolve();
        video.onerror = () => reject(new Error('VIDEO_LOAD_ERROR'));
      });

      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (!ctx) throw new Error('CTX_ERROR');

      // Add a max resolution safeguard just in case
      let width = video.videoWidth;
      let height = video.videoHeight;
      const MAX_DIM = 600;
      if (width > MAX_DIM || height > MAX_DIM) {
        const ratio = Math.min(MAX_DIM / width, MAX_DIM / height);
        width = Math.round(width * ratio);
        height = Math.round(height * ratio);
      }

      canvas.width = width;
      canvas.height = height;

      // Extract at 12 fps
      const fps = 12;
      const duration = video.duration;
      // Cap at 10 seconds of video (120 frames) to prevent memory crashes
      const totalFrames = Math.min(120, Math.max(1, Math.floor(duration * fps)));
      const extractedFrames: string[] = [];

      for (let i = 0; i < totalFrames; i++) {
        await new Promise<void>((resolve, reject) => {
          const timeToSeek = i / fps;

          const onSeeked = () => {
            video.removeEventListener('seeked', onSeeked);
            video.removeEventListener('error', onError);
            ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
            // using lower quality JPEG if possible, or standard PNG
            extractedFrames.push(canvas.toDataURL('image/png'));
            resolve();
          };

          const onError = () => {
            video.removeEventListener('seeked', onSeeked);
            video.removeEventListener('error', onError);
            reject(new Error('VIDEO_SEEK_ERROR'));
          };

          video.addEventListener('seeked', onSeeked);
          video.addEventListener('error', onError);
          video.currentTime = timeToSeek;
        });
      }

      const newGif: GifData = {
        id: Math.random().toString(36).substring(7),
        name: media.name || 'video',
        frames: extractedFrames,
        x: 0,
        y: 0
      };

      setGifs(prev => [...prev, newGif]);

    } catch (err) {
      console.error("Video processing failed:", err);
      setError('PROCESS_FAILED. UNABLE TO EXTRACT VIDEO.');
    } finally {
      URL.revokeObjectURL(url);
      setIsLoading(false);
    }
  };

  const processGif = async (file: File) => {
    setIsLoading(true);
    setError(null);

    try {
      const buffer = await file.arrayBuffer();
      const gif = parseGIF(buffer);
      const decompressedFrames = decompressFrames(gif, true);

      const framesToProcess = decompressedFrames;

      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d', { willReadFrequently: true });

      if (!ctx) throw new Error('CTX_ERROR');

      canvas.width = gif.lsd.width;
      canvas.height = gif.lsd.height;

      const tempCanvas = document.createElement('canvas');
      const tempCtx = tempCanvas.getContext('2d');
      tempCanvas.width = gif.lsd.width;
      tempCanvas.height = gif.lsd.height;

      if (!tempCtx) throw new Error('TEMP_CTX_ERROR');

      let frameImageData: ImageData | null = null;
      const extractedFrames: string[] = [];

      for (let i = 0; i < framesToProcess.length; i++) {
        const frame = framesToProcess[i];

        if (!frameImageData || frame.disposalType === 2) {
          ctx.clearRect(0, 0, canvas.width, canvas.height);
          frameImageData = ctx.createImageData(canvas.width, canvas.height);
        }

        const frameData = new ImageData(
          new Uint8ClampedArray(frame.patch),
          frame.dims.width,
          frame.dims.height
        );

        tempCtx.clearRect(0, 0, tempCanvas.width, tempCanvas.height);
        tempCtx.putImageData(frameData, frame.dims.left, frame.dims.top);

        ctx.drawImage(tempCanvas, 0, 0);
        extractedFrames.push(canvas.toDataURL('image/png'));
      }

      const newGif: GifData = {
        id: Math.random().toString(36).substring(7),
        name: file.name,
        frames: extractedFrames,
        x: 0,
        y: 0
      };

      setGifs(prev => [...prev, newGif]);
    } catch (err) {
      console.error(err);
      setError('PROCESS_FAILED. FILE MAY BE CORRUPT.');
    } finally {
      setIsLoading(false);
    }
  };

  const removeGif = (id: string) => {
    const target = gifs.find(g => g.id === id);
    if (target) {
      // Evict decoded frame images from the cache so memory doesn't leak when
      // gifs are added/removed repeatedly.
      const cache = imgCacheRef.current;
      for (const src of target.frames) cache.delete(src);
    }
    setGifs(prev => prev.filter(g => g.id !== id));
    if (selectedGifId === id) setSelectedGifId(null);
    if (gifs.length === 1) {
      setIsPlaying(false);
    }
  };

  const segmentGif = async (id: string) => {
    const gif = gifs.find(g => g.id === id);
    if (!gif || gif.isSegmented) return;

    abortFlagsRef.current[id] = false;
    const startTime = Date.now();

    // Ensure model is loaded. If preload already finished this resolves
    // instantly; if it's still in flight we await the same promise; if it
    // previously failed, getSegmenter() retries from scratch.
    try {
      if (modelStatus !== 'ready') setModelStatus('loading');
      await getSegmenter();
      setModelStatus('ready');
    } catch (err) {
      console.error('Model load failed:', err);
      setError('MODEL LOAD FAILED. CHECK NETWORK.');
      setModelStatus('error');
      return;
    }

    setSegmentationProgress({ id, current: 0, total: gif.frames.length, startTime });

    try {
      const newFrames: string[] = [];

      for (let i = 0; i < gif.frames.length; i++) {
        if (abortFlagsRef.current[id]) {
          setSegmentationProgress(null);
          return;
        }

        const segmentedDataUrl = await removeBackgroundFromFrame(gif.frames[i]);

        if (abortFlagsRef.current[id]) {
          setSegmentationProgress(null);
          return;
        }

        newFrames.push(segmentedDataUrl);
        setSegmentationProgress({ id, current: i + 1, total: gif.frames.length, startTime });
      }

      setGifs(prev => prev.map(g => g.id === id ? { ...g, frames: newFrames, isSegmented: true } : g));
    } catch (err) {
      console.error("Segmentation failed:", err);
      setError("SEGMENTATION FAILED. PLEASE TRY AGAIN.");
    } finally {
      setSegmentationProgress(null);
    }
  };

  const updateGifRotation = (id: string, rotZ: number) => {
    setGifs(prev => prev.map(g => g.id === id ? { ...g, rotZ } : g));
  };

  const updateGifPosition = (id: string, x: number, y: number) => {
    setGifs(prev => prev.map(g => g.id === id ? { ...g, x, y } : g));
  };

  // Mouse Controls for View Angle, Zoom & Pan
  const handlePointerDown = (e: React.PointerEvent) => {
    if ((e.target as HTMLElement).closest('.controls-panel')) return;
    if ((e.target as HTMLElement).closest('.hud-controls')) return;
    if ((e.target as HTMLElement).closest('.toolbar-btn')) return;
    if ((e.target as HTMLElement).closest('.zero-state-btn')) return;

    // Canvas hit-test: translate clientX/Y to canvas-local coords and walk the
    // front-to-back sorted quads from the last painted frame.
    const canvas = sceneCanvasRef.current;
    if (canvas) {
      const rect = canvas.getBoundingClientRect();
      const px = e.clientX - rect.left;
      const py = e.clientY - rect.top;
      for (const q of lastQuadsRef.current) {
        if (pointInQuad(px, py, q)) {
          setSelectedGifId(q.gifId);
          setDraggingGifId(q.gifId);
          lastMousePosRef.current = { x: e.clientX, y: e.clientY };
          e.currentTarget.setPointerCapture(e.pointerId);
          return;
        }
      }
    }

    setSelectedGifId(null);

    e.currentTarget.setPointerCapture(e.pointerId);
    isDraggingCanvasRef.current = true;
    lastMousePosRef.current = { x: e.clientX, y: e.clientY };

    if (e.button === 2 || e.shiftKey) {
      setIsPanning(true);
    } else {
      setIsPanning(false);
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (draggingGifId) {
      const dx = e.clientX - lastMousePosRef.current.x;
      const dy = e.clientY - lastMousePosRef.current.y;

      const rad = -rotationZ * Math.PI / 180;
      const scaleX = scale;
      const scaleY = scale * Math.cos(rotationX * Math.PI / 180);
      const effScaleY = Math.max(0.1, Math.abs(scaleY));

      const dxWorld = dx / scaleX;
      const dyWorld = dy / effScaleY;

      const adjustedDx = dxWorld * Math.cos(rad) - dyWorld * Math.sin(rad);
      const adjustedDy = dxWorld * Math.sin(rad) + dyWorld * Math.cos(rad);

      setGifs(prev => prev.map(g => {
        if (g.id === draggingGifId) {
          return { ...g, x: g.x + adjustedDx, y: g.y + adjustedDy };
        }
        return g;
      }));
      lastMousePosRef.current = { x: e.clientX, y: e.clientY };
      return;
    }

    if (!isDraggingCanvasRef.current) return;
    const dx = e.clientX - lastMousePosRef.current.x;
    const dy = e.clientY - lastMousePosRef.current.y;

    if (isPanning) {
      setPanX(prev => prev + dx);
      setPanY(prev => prev + dy);
    } else {
      setRotationZ(prev => prev + dx * 0.5);
      setRotationX(prev => prev - dy * 0.5);
    }

    lastMousePosRef.current = { x: e.clientX, y: e.clientY };
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    setDraggingGifId(null);
    isDraggingCanvasRef.current = false;
    setIsPanning(false);
    e.currentTarget.releasePointerCapture(e.pointerId);
  };

  const handleContextMenu = (e: React.MouseEvent) => {
    e.preventDefault();
  };

  // Compute the pan offset that would center the projected stack (or just the
  // selected gif, if one is selected) on the canvas. Uses the actual quads
  // from the most recent paint — same source of truth as hit-testing — so
  // motion, shear, scale, and rotation are all baked in already.
  const computeCenteringPan = useCallback((): { panX: number; panY: number } | null => {
    const canvas = sceneCanvasRef.current;
    if (!canvas || lastQuadsRef.current.length === 0) return null;
    // If a gif is selected, center on it; else center on the full stack.
    const filterId = selectedGifId && lastQuadsRef.current.some(q => q.gifId === selectedGifId)
      ? selectedGifId
      : null;
    const bbox = quadsBoundingBox(lastQuadsRef.current, filterId);
    if (!bbox) return null;
    const cx = (bbox.minX + bbox.maxX) / 2;
    const cy = (bbox.minY + bbox.maxY) / 2;
    const W = canvas.width;
    const H = canvas.height;
    // bbox is in canvas pixel space; current panX/Y is what produced these
    // quads, so the delta to recenter is just (target - current).
    const dx = W / 2 - cx;
    const dy = H / 2 - cy;
    return { panX: panX + dx, panY: panY + dy };
  }, [selectedGifId, panX, panY]);

  const centerAsset = () => {
    // Recenter camera pan so the projected stack bbox lands at canvas center.
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        const next = computeCenteringPan();
        if (next) {
          setPanX(next.panX);
          setPanY(next.panY);
        }
      });
    });
  };

  const setCameraPreset = (preset: 'iso' | 'front' | 'side') => {
    if (preset === 'iso') {
      setRotationX(60);
      setRotationZ(45);
    } else if (preset === 'front') {
      setRotationX(0);
      setRotationZ(0);
    } else if (preset === 'side') {
      setRotationX(0);
      setRotationZ(90);
    }
    setScale(1);
    // Defer centering one frame so the renderer has a chance to project quads
    // for the new camera angles before we read them.
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        const next = computeCenteringPan();
        if (next) {
          setPanX(next.panX);
          setPanY(next.panY);
        } else {
          setPanX(0);
          setPanY(0);
        }
      });
    });
  };

