                        : 'accent-white bg-white/20 [&::-webkit-slider-thumb]:bg-white'
                    )}
                    title="Rotate Z"
                  />
                  <span className={cn("text-[9px] w-8 text-right", theme === 'light' ? 'text-black/70' : 'text-white/70')}>{gif.rotZ || 0}°</span>
                </div>
              </div>
            );
          })()}
        </div>

        {/* Global Segmentation Loading Overlay */}
        {segmentationProgress && (
          <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm pointer-events-auto">
            <div className="bg-black/90 p-6 rounded-xl border border-white/20 shadow-2xl flex flex-col items-center min-w-[300px]">
              <div className="text-white text-xs mb-4 font-bold tracking-widest flex items-center justify-between w-full gap-4">
                <div className="flex items-center gap-3">
                  <div className="w-4 h-4 border-2 border-t-transparent border-white rounded-full animate-spin" />
                  SEGMENTING IMAGE...
                </div>
                <button 
                  onClick={(e) => { 
                    e.stopPropagation(); 
                    abortFlagsRef.current[segmentationProgress.id] = true; 
                    setSegmentationProgress(null);
                  }}
                  className="p-1.5 hover:bg-white/20 rounded transition-colors text-white/70 hover:text-white"
                  title="Cancel"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
              <div className="w-full h-2 bg-white/10 rounded-full overflow-hidden mb-3">
                <div 
                  className="h-full bg-indigo-500 transition-all duration-200" 
                  style={{ width: `${(segmentationProgress.current / segmentationProgress.total) * 100}%` }} 
                />
              </div>
              <div className="text-white/70 text-[10px] flex justify-between w-full">
                <span>{segmentationProgress.current} / {segmentationProgress.total} FRAMES</span>
                {segmentationProgress.current > 0 && (() => {
                  const remainingSeconds = Math.round(((Date.now() - segmentationProgress.startTime) / segmentationProgress.current) * (segmentationProgress.total - segmentationProgress.current) / 1000);
                  const mins = Math.floor(remainingSeconds / 60);
                  const secs = remainingSeconds % 60;
                  return (
                    <span>
                      EST: {mins > 0 ? `${mins}m ` : ''}{secs}s
                    </span>
                  );
                })()}
              </div>
            </div>
          </div>
        )}

        {/* Global Toast Notification */}
        {toastMessage && (
          <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-[60] pointer-events-none animate-in fade-in slide-in-from-bottom-4 duration-300">
            <div className={cn(
              "px-5 py-3 rounded-full shadow-2xl text-[11px] font-bold tracking-widest flex items-center gap-3 backdrop-blur-md",
              theme === 'light' ? 'bg-black/90 text-white border border-white/20' : 'bg-white/90 text-black border border-black/20'
            )}>
              <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
              {toastMessage}
            </div>
          </div>
        )}

        {/* Background-removal model status badge */}
        {modelStatus !== 'ready' && (
          <div className="absolute bottom-10 right-6 z-[60] pointer-events-none animate-in fade-in duration-300">
            <div className={cn(
              "px-3 py-2 rounded-full shadow-lg text-[10px] font-bold tracking-widest flex items-center gap-2 backdrop-blur-md",
              theme === 'light' ? 'bg-black/80 text-white' : 'bg-white/80 text-black'
            )}>
              {modelStatus === 'loading' ? (
                <>
                  <div className="w-2 h-2 rounded-full bg-yellow-500 animate-pulse" />
                  PREPARING BACKGROUND REMOVER
                </>
              ) : (
                <>
                  <div className="w-2 h-2 rounded-full bg-red-500" />
                  BACKGROUND REMOVER UNAVAILABLE
                </>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// Canvas renderer. The canvas IS the live scene AND the recorded source — what
// the user sees is what MediaRecorder captures. No CSS-3D scene exists anymore.
//
// Transform chain per frame (matches the original CSS chain conceptually):
//   outer:  translate(panX, panY) · scale(scale) · rotateX(rX) · rotateZ(rZ)
//   gif:    translate3d(spreadX + gif.x, gif.y, 0)
//   frame:  CENTER-anchored: rotateZ(gif.rotZ) · translate3d(xOff, yOff, zPos) · scale(curScale)
//           (gif.x/y refer to the frame's CENTER, not its top-left.)
//
// Motion presets ripple through the stack: each frame gets a phase-delayed
// motion offset so the wave propagates from front (z=0) to back (z=depth).
// RENDERER_MARK_v4_center_anchor

export type StyleMode = 'none' | 'hologram' | 'neon' | 'ghost';
export type MotionPreset = 'none' | 'wiggle' | 'shake' | 'earthquake' | 'pulse';

export interface SceneGif {
  id: string;
  x: number;
  y: number;
  rotZ: number;
  styleMode: StyleMode;
  frames: HTMLImageElement[]; // pre-decoded, indexable
  // Subset of `frames` indices to actually render (for the frame-density slider).
  // Sorted ascending. Each value is an index into `frames`.
  indices: number[];
  // The total number of frames in the active sampled set (so partial playback doesn't compress depth).
  totalStackSize: number;
}

export interface SceneState {
  gifs: SceneGif[];
  rotationX: number; // deg
  rotationZ: number; // deg
  scale: number;
  panX: number;
  panY: number;
  depth: number;
  shearOffset: number;
  scaleStep: number;
  dropShadow: number;
  multiGifSpread: number;
  motionPreset: MotionPreset;
  motionIntensity: number;
  theme: 'light' | 'dark';
  bgColor: string;
}

const DEG = Math.PI / 180;
// Per-frame phase delay for the motion ripple (front of stack leads).
// Front frame uses phase 0; subsequent (deeper) frames lag by this many ms.
const MOTION_PHASE_MS_PER_FRAME = 40;

export function styleModeToFilter(mode: StyleMode): { filter: string; composite: GlobalCompositeOperation } {
  if (mode === 'hologram') {
    return {
      filter: ' hue-rotate(90deg) saturate(200%) opacity(0.7) drop-shadow(0 0 10px cyan)',
      composite: 'screen',
    };
  }
  if (mode === 'neon') {
    return {
      filter: ' invert(1) sepia(1) saturate(5) hue-rotate(200deg) drop-shadow(0 0 5px magenta)',
      composite: 'screen',
    };
  }
  if (mode === 'ghost') {
    return {
      filter: ' grayscale(1) opacity(0.8)',
      composite: 'exclusion',
    };
  }
  return { filter: '', composite: 'source-over' };
}

// Time-driven equivalents of the old CSS keyframes. `phaseMs` is subtracted from
// the time so each frame in the stack can lag the previous one (ripple effect).
export function computeMotionOffset(
  preset: MotionPreset,
  intensity: number,
  timeMs: number,
  phaseMs: number = 0,
): { dx: number; dy: number; rot: number; scale: number } {
  if (preset === 'none' || intensity === 0) {
    return { dx: 0, dy: 0, rot: 0, scale: 1 };
  }
  const t = (timeMs - phaseMs) / 1000;
  const k = intensity; // 0..~3
  if (preset === 'wiggle') {
    const a = Math.sin((t / 2) * Math.PI * 2) * 3 * k;
    return { dx: 0, dy: 0, rot: a, scale: 1 };
  }
  if (preset === 'shake') {
    const p = ((t % 0.3) + 0.3) % 0.3 / 0.3;
    const dx = Math.sin(p * Math.PI * 4) * 4 * k;
    const dy = Math.cos(p * Math.PI * 4) * 2 * k;
    return { dx, dy, rot: 0, scale: 1 };
  }
  if (preset === 'earthquake') {
    const p = ((t % 0.4) + 0.4) % 0.4 / 0.4;
    const dx = (Math.sin(p * Math.PI * 6) + Math.sin(p * Math.PI * 13)) * 3 * k;
    const dy = (Math.cos(p * Math.PI * 7) + Math.sin(p * Math.PI * 11)) * 3 * k;
    return { dx, dy, rot: 0, scale: 1 };
  }
  if (preset === 'pulse') {
    const s = 1 + Math.sin((t / 2) * Math.PI * 2) * 0.05 * k;
    return { dx: 0, dy: 0, rot: 0, scale: s };
  }
  return { dx: 0, dy: 0, rot: 0, scale: 1 };
}

interface Vec3 { x: number; y: number; z: number; }

// Apply rotateZ then rotateX (outer camera, matching CSS right-to-left), then scale, then translate to canvas center.
function projectCamera(
  p: Vec3,
  rX: number, rZ: number, scale: number,
  panX: number, panY: number,
  canvasW: number, canvasH: number,
): { x: number; y: number; depth: number } {
  // 1. Rotate Z first (yaw)
  const cz = Math.cos(rZ * DEG), sz = Math.sin(rZ * DEG);
  const x1 = p.x * cz - p.y * sz;
  const y1 = p.x * sz + p.y * cz;
  const z1 = p.z;

  // 2. Rotate X second (pitch)
  const cx = Math.cos(rX * DEG), sx = Math.sin(rX * DEG);
  const x2 = x1;
  const y2 = y1 * cx - z1 * sx;
  const z2 = y1 * sx + z1 * cx;

  return {
    x: x2 * scale + panX + canvasW / 2,
    y: y2 * scale + panY + canvasH / 2,
    depth: z2,
  };
}

// Projects a frame-local corner through the full chain and returns 2D canvas coords.
// Chain (matches original CSS): scale → translate(xOff,yOff) → rotateZ(frameRot)
// → translate(frameCenterX, frameCenterY) → camera.
function projectCorner(
  localX: number, localY: number,
  frameCenterX: number, frameCenterY: number, frameZ: number,
  frameRotZdeg: number, frameScale: number,
  xOff: number, yOff: number,
  gifTX: number, gifTY: number,
  rX: number, rZ: number, camScale: number,
  panX: number, panY: number,
  canvasW: number, canvasH: number,
): { x: number; y: number; depth: number } {
  const s = frameScale;
  // Scale, then shear translate (in pre-rotation local space).
  const lx = localX * s + xOff;
  const ly = localY * s + yOff;
  // Rotate in local frame space (shear is in rotated space matches original).
  const cr = Math.cos(frameRotZdeg * DEG), sr = Math.sin(frameRotZdeg * DEG);
  const rx = lx * cr - ly * sr;
  const ry = lx * sr + ly * cr;
  const px = rx + frameCenterX + gifTX;
  const py = ry + frameCenterY + gifTY;
  const pz = frameZ;
  return projectCamera({ x: px, y: py, z: pz }, rX, rZ, camScale, panX, panY, canvasW, canvasH);
}

function affineFromCorners(
  tl: { x: number; y: number },
  tr: { x: number; y: number },
  bl: { x: number; y: number },
  w: number, h: number,
): [number, number, number, number, number, number] {
  const a = (tr.x - tl.x) / w;
  const b = (tr.y - tl.y) / w;
  const c = (bl.x - tl.x) / h;
  const d = (bl.y - tl.y) / h;
  return [a, b, c, d, tl.x, tl.y];
}

export function drawGrid(
  ctx: CanvasRenderingContext2D,
  w: number, h: number,
  bgColor: string,
  theme: 'light' | 'dark',
) {
  const line = theme === 'dark' ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)';
  ctx.fillStyle = bgColor;
  ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = line;
  ctx.lineWidth = 1;
  ctx.beginPath();
  const step = 40;
  for (let x = 0; x <= w; x += step) {
    ctx.moveTo(x + 0.5, 0);
    ctx.lineTo(x + 0.5, h);
  }
  for (let y = 0; y <= h; y += step) {
    ctx.moveTo(0, y + 0.5);
    ctx.lineTo(w, y + 0.5);
  }
  ctx.stroke();
}

interface DrawItem {
  gif: SceneGif;
  frameIdx: number;
  img: HTMLImageElement;
  depth: number;
  tl: { x: number; y: number };
  tr: { x: number; y: number };
  bl: { x: number; y: number };
  w: number;
  h: number;
  filter: string;
  composite: GlobalCompositeOperation;
}

export function renderScene(
  ctx: CanvasRenderingContext2D,
  state: SceneState,
  timeMs: number,
) {
  const canvas = ctx.canvas;
  const W = canvas.width;
  const H = canvas.height;

  drawGrid(ctx, W, H, state.bgColor, state.theme);

  const {
    gifs, rotationX, rotationZ, scale, panX, panY,
    depth, shearOffset, scaleStep, dropShadow,
    multiGifSpread, motionPreset, motionIntensity,
  } = state;

  const n = gifs.length;
  if (n === 0) return;

  const items: DrawItem[] = [];

  for (let gi = 0; gi < n; gi++) {
    const gif = gifs[gi];
    const spreadX = n > 1 ? (gi - (n - 1) / 2) * multiGifSpread : 0;
    const indices = gif.indices;
    const renderCount = indices.length;

    for (let pos = 0; pos < renderCount; pos++) {
      const i = indices[pos];
      const img = gif.frames[i];
      if (!img || !img.complete || img.naturalWidth === 0) continue;
      // Progress is computed against the rendered subset so the stack always
      // spans the full depth/scale range regardless of density.
      const progress = gif.totalStackSize > 1 ? pos / (gif.totalStackSize - 1) : 0;
      const phaseMs = pos * MOTION_PHASE_MS_PER_FRAME;
      const motion = computeMotionOffset(motionPreset, motionIntensity, timeMs, phaseMs);

      const gifTX = spreadX + gif.x + motion.dx;
      const gifTY = gif.y + motion.dy;
      const zPos = progress * depth;
      const xOff = progress * shearOffset;
      const yOff = progress * shearOffset;
      const curScale = (1 + (scaleStep - 1) * progress) * motion.scale;
      const w = img.naturalWidth;
      const h = img.naturalHeight;

      const frameCX = gifTX;
      const frameCY = gifTY;
      const frameRot = gif.rotZ + motion.rot;

      const tl = projectCorner(-w / 2, -h / 2, frameCX, frameCY, zPos, frameRot, curScale, xOff, yOff, 0, 0, rotationX, rotationZ, scale, panX, panY, W, H);
      const tr = projectCorner( w / 2, -h / 2, frameCX, frameCY, zPos, frameRot, curScale, xOff, yOff, 0, 0, rotationX, rotationZ, scale, panX, panY, W, H);
      const bl = projectCorner(-w / 2,  h / 2, frameCX, frameCY, zPos, frameRot, curScale, xOff, yOff, 0, 0, rotationX, rotationZ, scale, panX, panY, W, H);

      const cz = Math.cos(rotationZ * DEG), sz = Math.sin(rotationZ * DEG);
      const cx = Math.cos(rotationX * DEG), sx = Math.sin(rotationX * DEG);
      const y1 = frameCX * sz + frameCY * cz;
      const sortZ = y1 * sx + zPos * cx;

      // Build filter only if any effect is active. Empty string disables the
      // expensive ctx.filter pipeline.
      const { filter: modeFilter, composite } = styleModeToFilter(gif.styleMode);
      const dropPart = dropShadow > 0
        ? `drop-shadow(0px ${dropShadow}px ${dropShadow}px rgba(0,0,0,0.8))`
        : '';
      const filter = `${dropPart}${modeFilter}`.trim();

      items.push({ gif, frameIdx: i, img, depth: sortZ, tl, tr, bl, w, h, filter, composite });
    }
  }

  // Painter's algorithm: farther (smaller z after rotateX) drawn first.
  items.sort((a, b) => a.depth - b.depth);

  // Track current ctx state so we only re-set when changed.
  let lastFilter = '';
  let lastComposite: GlobalCompositeOperation = 'source-over';
  ctx.filter = 'none';
  ctx.globalCompositeOperation = 'source-over';

  for (const it of items) {
    if (it.composite !== lastComposite) {
      ctx.globalCompositeOperation = it.composite;
      lastComposite = it.composite;
    }
    const desiredFilter = it.filter || 'none';
    if (desiredFilter !== lastFilter) {
      ctx.filter = desiredFilter;
      lastFilter = desiredFilter;
    }
    const [a, b, c, d, e, f] = affineFromCorners(it.tl, it.tr, it.bl, it.w, it.h);
    ctx.setTransform(a, b, c, d, e, f);
    try {
      ctx.drawImage(it.img, 0, 0, it.w, it.h);
    } catch {
      // ignore broken frame
    }
  }
  // Reset state for next render.
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.filter = 'none';
  ctx.globalCompositeOperation = 'source-over';
}

export interface FrameQuad {
  gifId: string;
  frameIdx: number;
  depth: number;
  tl: { x: number; y: number };
  tr: { x: number; y: number };
  bl: { x: number; y: number };
  br: { x: number; y: number };
}

// Produces frame quads in canvas-space for hit-testing AND for layout helpers
// (centering, toolbar anchoring). Sorted front-to-back so the first
// point-in-quad match is the visible top frame.
export function projectFrameQuads(
  state: SceneState,
  W: number,
  H: number,
  timeMs: number,
): FrameQuad[] {
  const {
    gifs, rotationX, rotationZ, scale, panX, panY,
    depth, shearOffset, scaleStep, multiGifSpread,
    motionPreset, motionIntensity,
  } = state;
  const n = gifs.length;
  if (n === 0) return [];

  const out: FrameQuad[] = [];

  for (let gi = 0; gi < n; gi++) {
    const gif = gifs[gi];
    const spreadX = n > 1 ? (gi - (n - 1) / 2) * multiGifSpread : 0;
    const indices = gif.indices;
    const renderCount = indices.length;

    for (let pos = 0; pos < renderCount; pos++) {
      const i = indices[pos];
      const img = gif.frames[i];
      if (!img || !img.complete || img.naturalWidth === 0) continue;
      const progress = gif.totalStackSize > 1 ? pos / (gif.totalStackSize - 1) : 0;
      const phaseMs = pos * MOTION_PHASE_MS_PER_FRAME;
      const motion = computeMotionOffset(motionPreset, motionIntensity, timeMs, phaseMs);

      const gifTX = spreadX + gif.x + motion.dx;
      const gifTY = gif.y + motion.dy;
      const zPos = progress * depth;
      const xOff = progress * shearOffset;
      const yOff = progress * shearOffset;
      const curScale = (1 + (scaleStep - 1) * progress) * motion.scale;
      const w = img.naturalWidth;
      const h = img.naturalHeight;
      const frameCX = gifTX;
      const frameCY = gifTY;
      const frameRot = gif.rotZ + motion.rot;
      const tl = projectCorner(-w / 2, -h / 2, frameCX, frameCY, zPos, frameRot, curScale, xOff, yOff, 0, 0, rotationX, rotationZ, scale, panX, panY, W, H);
      const tr = projectCorner( w / 2, -h / 2, frameCX, frameCY, zPos, frameRot, curScale, xOff, yOff, 0, 0, rotationX, rotationZ, scale, panX, panY, W, H);
      const bl = projectCorner(-w / 2,  h / 2, frameCX, frameCY, zPos, frameRot, curScale, xOff, yOff, 0, 0, rotationX, rotationZ, scale, panX, panY, W, H);
      const br = projectCorner( w / 2,  h / 2, frameCX, frameCY, zPos, frameRot, curScale, xOff, yOff, 0, 0, rotationX, rotationZ, scale, panX, panY, W, H);

      const cz = Math.cos(rotationZ * DEG), sz = Math.sin(rotationZ * DEG);
      const cx = Math.cos(rotationX * DEG), sx = Math.sin(rotationX * DEG);
      const y1 = frameCX * sz + frameCY * cz;
      const sortZ = y1 * sx + zPos * cx;

      out.push({ gifId: gif.id, frameIdx: i, depth: sortZ, tl, tr, bl, br });
    }
  }
  // Front-to-back: larger depth = nearer camera after rotateX.
  out.sort((a, b) => b.depth - a.depth);
  return out;
}

export function pointInQuad(
  px: number, py: number,
  q: { tl: { x: number; y: number }; tr: { x: number; y: number }; br: { x: number; y: number }; bl: { x: number; y: number } },
): boolean {
  const tri = (ax: number, ay: number, bx: number, by: number, cx: number, cy: number): boolean => {
    const v0x = cx - ax, v0y = cy - ay;
    const v1x = bx - ax, v1y = by - ay;
    const v2x = px - ax, v2y = py - ay;
    const dot00 = v0x * v0x + v0y * v0y;
    const dot01 = v0x * v1x + v0y * v1y;
    const dot02 = v0x * v2x + v0y * v2y;
    const dot11 = v1x * v1x + v1y * v1y;
    const dot12 = v1x * v2x + v1y * v2y;
    const denom = dot00 * dot11 - dot01 * dot01;
    if (Math.abs(denom) < 1e-9) return false;
    const inv = 1 / denom;
    const u = (dot11 * dot02 - dot01 * dot12) * inv;
    const v = (dot00 * dot12 - dot01 * dot02) * inv;
    return u >= 0 && v >= 0 && (u + v) <= 1;
  };
  return tri(q.tl.x, q.tl.y, q.tr.x, q.tr.y, q.br.x, q.br.y)
      || tri(q.tl.x, q.tl.y, q.br.x, q.br.y, q.bl.x, q.bl.y);
}

// Helper for the "center" button and view-preset recentering.
// Returns the canvas-space bbox of all (or selected) projected quads.
export function quadsBoundingBox(
  quads: FrameQuad[],
  filterGifId?: string | null,
): { minX: number; minY: number; maxX: number; maxY: number } | null {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  let count = 0;
  for (const q of quads) {
    if (filterGifId && q.gifId !== filterGifId) continue;
    for (const p of [q.tl, q.tr, q.bl, q.br]) {
      if (p.x < minX) minX = p.x;
      if (p.y < minY) minY = p.y;
      if (p.x > maxX) maxX = p.x;
      if (p.y > maxY) maxY = p.y;
    }
    count++;
  }
  if (count === 0) return null;
  return { minX, minY, maxX, maxY };
}

// React hook that records a given <canvas> element. The canvas is the live scene,
// so "what you see is what you record" by construction.
//
// Flow integration: saves the recording to the user's Flow gallery via Flow.save.
// Flow.save only accepts image/png, image/jpeg, video/mp4 — so we prefer mp4 from
// MediaRecorder when available (Safari + recent Chromium). If only webm is
// supported by the browser, we surface a friendly error instead of a broken save.

import type React from 'react';
import { useCallback, useEffect, useRef, useState } from 'react';
import { Flow } from 'flow-sdk';

function pickMime(): string {
  const candidates = [
    'video/mp4',
    'video/webm;codecs=vp9',
    'video/webm;codecs=vp8',
    'video/webm',
  ];
  for (const m of candidates) {
    if (typeof MediaRecorder !== 'undefined' && MediaRecorder.isTypeSupported?.(m)) return m;
  }
  return 'video/webm';
}

function blobToBase64(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = reader.result as string;
      // strip "data:<mime>;base64," prefix
      const comma = result.indexOf(',');
      resolve(comma >= 0 ? result.slice(comma + 1) : result);
    };
    reader.onerror = () => reject(reader.error || new Error('READ_ERROR'));
    reader.readAsDataURL(blob);
  });
}

export function useSceneRecorder(
  canvasRef: React.RefObject<HTMLCanvasElement | null>,
) {
  const [isRecording, setIsRecording] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [toast, setToast] = useState<string | null>(null);

  const recorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const startTimeRef = useRef<number>(0);
  const streamRef = useRef<MediaStream | null>(null);
  const stopRequestedRef = useRef(false);

  useEffect(() => () => {
    try { recorderRef.current?.stop(); } catch { /* noop */ }
    try { streamRef.current?.getTracks().forEach(t => t.stop()); } catch { /* noop */ }
  }, []);

  const start = useCallback(async () => {
    if (isRecording || isSaving) return;
    setError(null);
    setToast(null);
    try {
      const canvas = canvasRef.current;
      if (!canvas) throw new Error('NO_CANVAS');
      const stream: MediaStream = canvas.captureStream(30);
      streamRef.current = stream;
      const mimeType = pickMime();
      const rec = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 6_000_000 });
      recorderRef.current = rec;
      chunksRef.current = [];
      stopRequestedRef.current = false;

      rec.ondataavailable = (e: BlobEvent) => {
        if (e.data && e.data.size > 0) chunksRef.current.push(e.data);
      };
      rec.onerror = () => setError('Recording error');

      rec.onstop = async () => {
        setIsRecording(false);
        try {
          if (chunksRef.current.length === 0) throw new Error('EMPTY_RECORDING');
          const blob = new Blob(chunksRef.current, { type: mimeType });

          // Flow.save only allows image/png, image/jpeg, video/mp4.
          if (mimeType !== 'video/mp4') {
            setError('RECORDING NOT SUPPORTED IN THIS BROWSER (MP4 UNAVAILABLE)');
            return;
          }

          setIsSaving(true);
          const base64 = await blobToBase64(blob);
          await Flow.save({
            base64,
            mimeType: 'video/mp4',
            name: `Frame Deconstructor Recording ${new Date().toISOString()}`,
          });
          setToast('RECORDING SAVED TO GALLERY');
        } catch (err: any) {
          setError(String(err?.message || err));
        } finally {
          setIsSaving(false);
          chunksRef.current = [];
          try { streamRef.current?.getTracks().forEach(t => t.stop()); } catch { /* noop */ }
          streamRef.current = null;
          recorderRef.current = null;
        }
      };

      startTimeRef.current = performance.now();
      rec.start(100); // 100ms timeslice → frequent ondataavailable
      setIsRecording(true);
    } catch (err: any) {
      setError(String(err?.message || err));
      setIsRecording(false);
    }
  }, [isRecording, isSaving, canvasRef]);

  const stop = useCallback(async () => {
    const rec = recorderRef.current;
    if (!rec || rec.state === 'inactive') return;
    if (stopRequestedRef.current) return;
    stopRequestedRef.current = true;

    const elapsed = performance.now() - startTimeRef.current;
    const minMs = 500;
    if (elapsed < minMs) await new Promise(r => setTimeout(r, minMs - elapsed));

    try { rec.requestData(); } catch { /* noop */ }
    await new Promise(r => setTimeout(r, 50));
    try { rec.stop(); } catch { /* noop */ }
  }, []);

  return { isRecording, isSaving, error, toast, start, stop };
}

// Background removal using transformers.js + Xenova/modnet
// Loaded from Hugging Face CDN at runtime (do not bundle the ONNX weights).

import {
  env,
  AutoModel,
  AutoProcessor,
  RawImage,
  type PreTrainedModel,
  type Processor,
} from '@huggingface/transformers';

// REQUIRED for sandboxed environment:
// 1. Force remote model loading from the HF CDN.
env.allowLocalModels = false;
// 2. Disable Cache API usage (throws SecurityError in opaque origin sandbox).
env.useBrowserCache = false;

// IMPORTANT: configure the ONNX Runtime Web (WASM) backend defensively so the
// model can still load when WebGPU is unavailable (e.g. inside a shared AI
// Studio iframe that doesn't grant the `webgpu` permission policy).
//
// 1. `proxy = false`  – running ORT in a Web Worker triggers a
//    `ReferenceError: document is not defined` in the current
//    `onnxruntime-web` build because its WASM-loader code path references
//    `document` at module top-level. We pay a small main-thread cost in
//    exchange for a backend that actually initializes.
// 2. `numThreads = 1`  – threaded WASM requires `crossOriginIsolated`
//    (SharedArrayBuffer). Shared AI Studio embeds frequently don't set the
//    required COOP/COEP headers, which makes threaded WASM fail with
//    "no available backend found". Single-threaded WASM works everywhere.
if (env.backends?.onnx?.wasm) {
  env.backends.onnx.wasm.proxy = false;
  env.backends.onnx.wasm.numThreads = 1;
}

const MODEL_ID = 'Xenova/modnet';

type Segmenter = {
  model: PreTrainedModel;
  processor: Processor;
};

let segmenterPromise: Promise<Segmenter> | null = null;

async function tryLoadOnDevice(
  device: 'webgpu' | 'wasm',
): Promise<Segmenter> {
  const model = await AutoModel.from_pretrained(MODEL_ID, {
    device,
    dtype: 'fp32',
  });
  const processor = await AutoProcessor.from_pretrained(MODEL_ID);
  return { model, processor };
}

async function isWebGpuUsable(): Promise<boolean> {
  try {
    // Avoid even attempting WebGPU when the API or an adapter isn't available
    // – this is the common case inside shared AI Studio iframes that don't
    // expose the `webgpu` permission policy.
    const gpu = (navigator as unknown as { gpu?: { requestAdapter: () => Promise<unknown> } }).gpu;
    if (!gpu) return false;
    const adapter = await gpu.requestAdapter();
    return adapter != null;
  } catch {
    return false;
  }
}

async function loadSegmenter(): Promise<Segmenter> {
  if (await isWebGpuUsable()) {
    try {
      return await tryLoadOnDevice('webgpu');
    } catch (err) {
      console.warn(
        '[segmentation] WebGPU load failed, falling back to WASM:',
        err,
      );
    }
  } else {
    console.info('[segmentation] WebGPU unavailable, using WASM backend.');
  }

  try {
    return await tryLoadOnDevice('wasm');
  } catch (err) {
    console.error('[segmentation] WASM backend also failed:', err);
    throw new Error(
      'Background removal model failed to load. ' +
        'This usually happens when the embedding context blocks both WebGPU ' +
        'and WebAssembly. Try opening the app in a new tab.',
    );
  }
}

export function getSegmenter(): Promise<Segmenter> {
  if (!segmenterPromise) {
    segmenterPromise = loadSegmenter().catch((err) => {
      // Reset so callers can retry after a failure.
      segmenterPromise = null;
      throw err;
    });
  }
  return segmenterPromise;
}

/**
 * Remove the background from a single frame.
 * @param dataUrl  The source image as a data URL (png/jpeg).
 * @returns        A PNG data URL with the background pixels made transparent.
 */
export async function removeBackgroundFromFrame(dataUrl: string): Promise<string> {
  const { model, processor } = await getSegmenter();

  const image = await RawImage.fromURL(dataUrl);
  const { pixel_values } = await processor(image);
  const { output } = await model({ input: pixel_values });

  // Resize mask back to the source image dimensions.
  const maskRaw = await RawImage.fromTensor(output[0].mul(255).to('uint8')).resize(
    image.width,
    image.height,
  );

  // Composite: copy source RGB, replace alpha with mask.
  const canvas = document.createElement('canvas');
  canvas.width = image.width;
  canvas.height = image.height;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Failed to acquire 2D canvas context');

  // Draw the source image via an Image element (RawImage -> dataURL -> Image).
  const srcImg = new Image();
  srcImg.src = dataUrl;
  await new Promise<void>((resolve, reject) => {
    srcImg.onload = () => resolve();
    srcImg.onerror = () => reject(new Error('Failed to decode source image'));
  });
  ctx.drawImage(srcImg, 0, 0, image.width, image.height);

  const pixelData = ctx.getImageData(0, 0, image.width, image.height);
  const maskData = maskRaw.data;
  for (let i = 0; i < maskData.length; i++) {
    pixelData.data[i * 4 + 3] = maskData[i];
  }
  ctx.putImageData(pixelData, 0, 0);

  return canvas.toDataURL('image/png');
}
